{"source": "def investigate(context, acquire):
    receipts = acquire('history')

    def simulate(actions, put_mode, channel_mode, trigger):
        committed = {}
        tx = {'main': None, 'other': None}
        changes = {'main': 0, 'other': 0}
        total = {'main': 0, 'other': 0}

        def state_of(conn):
            if tx[conn] is not None:
                return tx[conn]
            return committed

        def do_put(conn, key, value):
            state = state_of(conn)
            if key in state:
                if put_mode == 'ignore':
                    return 0
                state[key] = value
                return 1
            state[key] = value
            return 1

        def do_update(conn, key, value):
            state = state_of(conn)
            if key in state:
                state[key] = value
                return 1
            return 0

        def do_delete(conn, key):
            state = state_of(conn)
            if key in state:
                del state[key]
                return 1
            return 0

        for act in actions:
            op = act.get('op')
            conn = act.get('connection', 'main')
            if op == 'put':
                n = do_put(conn, act['key'], act['value'])
            elif op == 'update':
                n = do_update(conn, act['key'], act['value'])
            elif op == 'delete':
                n = do_delete(conn, act['key'])
            elif op == 'begin':
                if tx[conn] is None:
                    tx[conn] = dict(committed)
                continue
            elif op == 'commit':
                if tx[conn] is not None:
                    committed.clear()
                    committed.update(tx[conn])
                    tx[conn] = None
                continue
            elif op == 'rollback':
                if tx[conn] is not None:
                    tx[conn] = None
                continue
            else:
                continue
            changes[conn] += n
            total[conn] += n
            if trigger and n > 0:
                total[conn] += 1

        if channel_mode == 'changes':
            ch = changes['main']
        elif channel_mode == 'total_main':
            ch = total['main']
        else:
            ch = total['main'] + total['other']
        return ch, len(committed), sum(committed.values())

    put_modes = ['ignore', 'replace', 'update']
    channel_modes = ['changes', 'total_main', 'total_both']
    triggers = [False, True]

    candidates = []
    for pm in put_modes:
        for cm in channel_modes:
            for tr in triggers:
                ok = True
                for r in receipts:
                    ch, cc, cs = simulate(r['actions'], pm, cm, tr)
                    obs = r['observed']
                    if ch != obs['channel'] or cc != obs['committed_count'] or cs != obs['committed_sum']:
                        ok = False
                        break
                if ok:
                    candidates.append((pm, cm, tr))

    if not candidates:
        return {'value': None, 'unresolved': True}

    goal = context.get('goal')
    actions = context.get('actions', [])
    results = set()
    for pm, cm, tr in candidates:
        ch, cc, cs = simulate(actions, pm, cm, tr)
        if goal == 'channel':
            results.add(ch)
        elif goal == 'committed_count':
            results.add(cc)
        elif goal == 'committed_sum':
            results.add(cs)
        else:
            return {'value': None, 'unresolved': True}

    if len(results) == 1:
        return {'value': results.pop(), 'unresolved': False}
    return {'value': None, 'unresolved': True}
", "scope": "The source family is the 18 combinations of three put modes (INSERT OR IGNORE, INSERT OR REPLACE, INSERT ... ON CONFLICT DO UPDATE), three channel modes (main changes(), main total_changes, main+other total_changes), and presence/absence of one AFTER INSERT trigger. The predictor enumerates all 18, filters by calibration receipts, and returns a value only when all surviving candidates agree on the goal.", "lesson": "Calibration receipts show repeated puts on the same key leave committed_sum equal to the first value and channel 2 for a single put, consistent with INSERT OR IGNORE plus a channel counting direct row changes. The predictor generalizes by simulating all family members and intersecting their predictions."}
